#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    vector<int> a1, a2;
    int n1 = n / 2;

    function<void(int, int)> sums1 = [&](int i, int sum) {
        if (i == n1) {
            a1.push_back(sum);
        } else {
            sums1(i + 1, (sum + a[i]) % m);
            sums1(i + 1, sum);
        }
    };

    function<void(int, int)> sums2 = [&](int i, int sum) {
        if (i == n) {
            a2.push_back(sum);
        } else {
            sums2(i + 1, (sum + a[i]) % m);
            sums2(i + 1, sum);
        }
    };

    sums1(0, 0);
    sums2(n1, 0);

    int ans = 0;
    int end = (int)a2.size() - 1;

    set<int> a1_set(a1.begin(), a1.end());
    vector<int> a1_unique(a1_set.begin(), a1_set.end());
    sort(a1_unique.begin(), a1_unique.end());

    for (int i : a2) {
        int j = (int)(std::lower_bound(a1_unique.begin(), a1_unique.end(), m - i) - a1_unique.begin());
        if (j > 0) {
            int k = a1_unique[j - 1] + i;
            if (k > ans) {
                ans = k;
            }
        }
        if (j < (int)a1_unique.size()) {
            int k = a1_unique[j] + i;
            if (k > ans) {
                ans = k;
            }
        }
    }

    cout << ans << "\n";

    return 0;
}
